-- FindMySpare v2: marketplace checkout/payments, Garage OS, Vehicle Passport.
-- Add-only: creates types/tables/indexes and adds columns. No drops, renames
-- or data deletion. Generated by drizzle-kit (old main schema → this branch)
-- and verified: old schema + this file == new schema (drizzle reports no diff).
--
-- Run once against production BEFORE deploying the new API:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f drizzle/manual/0001_v2_marketplace_garage_passport.sql
BEGIN;

CREATE TYPE "public"."part_type" AS ENUM('genuine', 'oes', 'aftermarket', 'used', 'refurbished');
CREATE TYPE "public"."order_payment_status" AS ENUM('pending', 'paid', 'refunded');
CREATE TYPE "public"."order_source" AS ENUM('cart', 'quote', 'job');
CREATE TYPE "public"."vehicle_access_status" AS ENUM('pending', 'granted', 'revoked');
CREATE TYPE "public"."vehicle_segment" AS ENUM('car', 'bike', 'scooter', 'commercial');
CREATE TYPE "public"."fitment_source" AS ENUM('seller', 'order_confirmed', 'job_fitted');
CREATE TYPE "public"."invoice_status" AS ENUM('unpaid', 'paid', 'void');
CREATE TYPE "public"."job_item_kind" AS ENUM('part', 'labour');
CREATE TYPE "public"."job_item_source" AS ENUM('own_stock', 'marketplace', 'customer');
CREATE TYPE "public"."job_status" AS ENUM('open', 'estimate_sent', 'approved', 'in_progress', 'ready', 'invoiced', 'paid', 'cancelled');
CREATE TYPE "public"."payment_purpose" AS ENUM('checkout', 'invoice');
CREATE TYPE "public"."payment_status" AS ENUM('created', 'succeeded', 'failed');
CREATE TABLE "garages" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"owner_id" uuid NOT NULL,
	"name" varchar(160) NOT NULL,
	"gstin" varchar(20),
	"phone" varchar(20),
	"address_line" varchar(255),
	"city" varchar(100),
	"state" varchar(100),
	"pincode" varchar(10),
	"upi_id" varchar(100),
	"invoice_prefix" varchar(10) DEFAULT 'INV' NOT NULL,
	"next_invoice_no" integer DEFAULT 1 NOT NULL,
	"specialisations" jsonb DEFAULT '[]'::jsonb,
	"verified" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "vehicle_access" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"vehicle_id" uuid NOT NULL,
	"garage_id" uuid NOT NULL,
	"status" "vehicle_access_status" DEFAULT 'pending' NOT NULL,
	"token" varchar(40) NOT NULL,
	"requested_at" timestamp with time zone DEFAULT now() NOT NULL,
	"decided_at" timestamp with time zone
);

CREATE TABLE "vehicle_makes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" varchar(80) NOT NULL,
	"slug" varchar(80) NOT NULL,
	CONSTRAINT "vehicle_makes_name_unique" UNIQUE("name"),
	CONSTRAINT "vehicle_makes_slug_unique" UNIQUE("slug")
);

CREATE TABLE "vehicle_models" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"make_id" uuid NOT NULL,
	"name" varchar(80) NOT NULL,
	"segment" "vehicle_segment" DEFAULT 'car' NOT NULL
);

CREATE TABLE "vehicle_variants" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"model_id" uuid NOT NULL,
	"name" varchar(80) NOT NULL,
	"fuel" varchar(20) NOT NULL,
	"year_from" integer NOT NULL,
	"year_to" integer
);

CREATE TABLE "vehicles" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"reg_no" varchar(15) NOT NULL,
	"vin" varchar(20),
	"variant_id" uuid,
	"make_name" varchar(80) NOT NULL,
	"model_name" varchar(80) NOT NULL,
	"variant_name" varchar(80),
	"fuel" varchar(20),
	"year" integer,
	"segment" "vehicle_segment" DEFAULT 'car' NOT NULL,
	"color" varchar(40),
	"owner_id" uuid,
	"nickname" varchar(60),
	"odometer_km" integer,
	"share_token" varchar(40),
	"share_sections" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "fitments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"product_id" uuid,
	"part_number" varchar(100),
	"make_name" varchar(80) NOT NULL,
	"model_name" varchar(80) NOT NULL,
	"variant_name" varchar(80),
	"year" integer,
	"source" "fitment_source" NOT NULL,
	"confirmed_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "fitted_parts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"vehicle_id" uuid NOT NULL,
	"job_card_id" uuid,
	"job_item_id" uuid,
	"order_id" uuid,
	"garage_name" varchar(160),
	"name" varchar(255) NOT NULL,
	"part_number" varchar(100),
	"brand" varchar(100),
	"serial_no" varchar(100),
	"seller_name" varchar(160),
	"fitted_at" timestamp with time zone DEFAULT now() NOT NULL,
	"odometer_km" integer,
	"warranty_until" timestamp with time zone,
	"fit_confirmed" boolean
);

CREATE TABLE "invoices" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"garage_id" uuid NOT NULL,
	"job_card_id" uuid NOT NULL,
	"vehicle_id" uuid NOT NULL,
	"number" varchar(30) NOT NULL,
	"issued_at" timestamp with time zone DEFAULT now() NOT NULL,
	"seller" jsonb NOT NULL,
	"customer" jsonb NOT NULL,
	"vehicle" jsonb NOT NULL,
	"lines" jsonb NOT NULL,
	"taxable" numeric(12, 2) NOT NULL,
	"cgst" numeric(12, 2) NOT NULL,
	"sgst" numeric(12, 2) NOT NULL,
	"total" numeric(12, 2) NOT NULL,
	"content_hash" varchar(64) NOT NULL,
	"verify_code" varchar(20) NOT NULL,
	"pay_token" varchar(40) NOT NULL,
	"status" "invoice_status" DEFAULT 'unpaid' NOT NULL,
	"paid_at" timestamp with time zone,
	"payment_method" varchar(30)
);

CREATE TABLE "job_cards" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"garage_id" uuid NOT NULL,
	"vehicle_id" uuid NOT NULL,
	"number" varchar(20) NOT NULL,
	"customer_name" varchar(160),
	"customer_phone" varchar(20),
	"odometer_km" integer,
	"complaint" text,
	"inspection" jsonb DEFAULT '[]'::jsonb,
	"status" "job_status" DEFAULT 'open' NOT NULL,
	"estimate_token" varchar(40),
	"estimate_sent_at" timestamp with time zone,
	"approved_at" timestamp with time zone,
	"completed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "job_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"job_card_id" uuid NOT NULL,
	"kind" "job_item_kind" NOT NULL,
	"name" varchar(255) NOT NULL,
	"part_number" varchar(100),
	"brand" varchar(100),
	"hsn_sac" varchar(12),
	"quantity" integer DEFAULT 1 NOT NULL,
	"unit_price" numeric(12, 2) NOT NULL,
	"gst_rate" integer DEFAULT 18 NOT NULL,
	"approved" boolean DEFAULT true NOT NULL,
	"source" "job_item_source" DEFAULT 'own_stock' NOT NULL,
	"inquiry_id" uuid,
	"order_id" uuid,
	"seller_name" varchar(160),
	"warranty_months" integer DEFAULT 0 NOT NULL,
	"serial_no" varchar(100),
	"fitted" boolean DEFAULT false NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "checkouts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"buyer_id" uuid NOT NULL,
	"shipping_address_id" uuid,
	"items_total" numeric(12, 2) NOT NULL,
	"delivery_fee" numeric(12, 2) DEFAULT '0' NOT NULL,
	"platform_fee" numeric(12, 2) DEFAULT '0' NOT NULL,
	"total" numeric(12, 2) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "payments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"purpose" "payment_purpose" NOT NULL,
	"ref_id" uuid NOT NULL,
	"payer_id" uuid,
	"amount" numeric(12, 2) NOT NULL,
	"currency" varchar(3) DEFAULT 'INR' NOT NULL,
	"provider" varchar(20) DEFAULT 'mock' NOT NULL,
	"method" varchar(20),
	"status" "payment_status" DEFAULT 'created' NOT NULL,
	"provider_ref" varchar(60),
	"failure_reason" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp with time zone
);

CREATE TABLE "reviews" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"product_id" uuid,
	"supplier_id" uuid NOT NULL,
	"buyer_id" uuid NOT NULL,
	"rating" integer NOT NULL,
	"comment" text,
	"fit_confirmed" boolean,
	"vehicle" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE "products" ADD COLUMN "mrp" numeric(12, 2);
ALTER TABLE "products" ADD COLUMN "brand" varchar(100);
ALTER TABLE "products" ADD COLUMN "part_type" "part_type" DEFAULT 'aftermarket' NOT NULL;
ALTER TABLE "orders" ADD COLUMN "payment_status" "order_payment_status" DEFAULT 'pending' NOT NULL;
ALTER TABLE "orders" ADD COLUMN "checkout_id" uuid;
ALTER TABLE "orders" ADD COLUMN "source" "order_source" DEFAULT 'cart' NOT NULL;
ALTER TABLE "orders" ADD COLUMN "job_card_id" uuid;
ALTER TABLE "orders" ADD COLUMN "delivery_fee" numeric(12, 2) DEFAULT '0' NOT NULL;
ALTER TABLE "inquiries" ADD COLUMN "vehicle_id" uuid;
ALTER TABLE "inquiries" ADD COLUMN "job_card_id" uuid;
ALTER TABLE "inquiries" ADD COLUMN "city" varchar(100);
ALTER TABLE "bids" ADD COLUMN "brand" varchar(100);
ALTER TABLE "bids" ADD COLUMN "part_number" varchar(100);
ALTER TABLE "garages" ADD CONSTRAINT "garages_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "vehicle_access" ADD CONSTRAINT "vehicle_access_vehicle_id_vehicles_id_fk" FOREIGN KEY ("vehicle_id") REFERENCES "public"."vehicles"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "vehicle_access" ADD CONSTRAINT "vehicle_access_garage_id_garages_id_fk" FOREIGN KEY ("garage_id") REFERENCES "public"."garages"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "vehicle_models" ADD CONSTRAINT "vehicle_models_make_id_vehicle_makes_id_fk" FOREIGN KEY ("make_id") REFERENCES "public"."vehicle_makes"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "vehicle_variants" ADD CONSTRAINT "vehicle_variants_model_id_vehicle_models_id_fk" FOREIGN KEY ("model_id") REFERENCES "public"."vehicle_models"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "vehicles" ADD CONSTRAINT "vehicles_variant_id_vehicle_variants_id_fk" FOREIGN KEY ("variant_id") REFERENCES "public"."vehicle_variants"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "vehicles" ADD CONSTRAINT "vehicles_owner_id_users_id_fk" FOREIGN KEY ("owner_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "fitments" ADD CONSTRAINT "fitments_confirmed_by_users_id_fk" FOREIGN KEY ("confirmed_by") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "fitted_parts" ADD CONSTRAINT "fitted_parts_vehicle_id_vehicles_id_fk" FOREIGN KEY ("vehicle_id") REFERENCES "public"."vehicles"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "fitted_parts" ADD CONSTRAINT "fitted_parts_job_card_id_job_cards_id_fk" FOREIGN KEY ("job_card_id") REFERENCES "public"."job_cards"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "fitted_parts" ADD CONSTRAINT "fitted_parts_job_item_id_job_items_id_fk" FOREIGN KEY ("job_item_id") REFERENCES "public"."job_items"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "fitted_parts" ADD CONSTRAINT "fitted_parts_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_garage_id_garages_id_fk" FOREIGN KEY ("garage_id") REFERENCES "public"."garages"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_job_card_id_job_cards_id_fk" FOREIGN KEY ("job_card_id") REFERENCES "public"."job_cards"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_vehicle_id_vehicles_id_fk" FOREIGN KEY ("vehicle_id") REFERENCES "public"."vehicles"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "job_cards" ADD CONSTRAINT "job_cards_garage_id_garages_id_fk" FOREIGN KEY ("garage_id") REFERENCES "public"."garages"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "job_cards" ADD CONSTRAINT "job_cards_vehicle_id_vehicles_id_fk" FOREIGN KEY ("vehicle_id") REFERENCES "public"."vehicles"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "job_items" ADD CONSTRAINT "job_items_job_card_id_job_cards_id_fk" FOREIGN KEY ("job_card_id") REFERENCES "public"."job_cards"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "job_items" ADD CONSTRAINT "job_items_inquiry_id_inquiries_id_fk" FOREIGN KEY ("inquiry_id") REFERENCES "public"."inquiries"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "job_items" ADD CONSTRAINT "job_items_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "checkouts" ADD CONSTRAINT "checkouts_buyer_id_users_id_fk" FOREIGN KEY ("buyer_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "checkouts" ADD CONSTRAINT "checkouts_shipping_address_id_addresses_id_fk" FOREIGN KEY ("shipping_address_id") REFERENCES "public"."addresses"("id") ON DELETE no action ON UPDATE no action;
ALTER TABLE "payments" ADD CONSTRAINT "payments_payer_id_users_id_fk" FOREIGN KEY ("payer_id") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_product_id_products_id_fk" FOREIGN KEY ("product_id") REFERENCES "public"."products"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_supplier_id_users_id_fk" FOREIGN KEY ("supplier_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "reviews" ADD CONSTRAINT "reviews_buyer_id_users_id_fk" FOREIGN KEY ("buyer_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
CREATE UNIQUE INDEX "garages_owner_uq" ON "garages" USING btree ("owner_id");
CREATE UNIQUE INDEX "vehicle_access_pair_uq" ON "vehicle_access" USING btree ("vehicle_id","garage_id");
CREATE UNIQUE INDEX "vehicle_access_token_uq" ON "vehicle_access" USING btree ("token");
CREATE INDEX "vehicle_models_make_idx" ON "vehicle_models" USING btree ("make_id");
CREATE INDEX "vehicle_variants_model_idx" ON "vehicle_variants" USING btree ("model_id");
CREATE UNIQUE INDEX "vehicles_reg_no_uq" ON "vehicles" USING btree ("reg_no");
CREATE INDEX "vehicles_owner_idx" ON "vehicles" USING btree ("owner_id");
CREATE UNIQUE INDEX "vehicles_share_token_uq" ON "vehicles" USING btree ("share_token");
CREATE INDEX "fitments_product_idx" ON "fitments" USING btree ("product_id");
CREATE INDEX "fitments_model_idx" ON "fitments" USING btree ("make_name","model_name");
CREATE INDEX "fitted_parts_vehicle_idx" ON "fitted_parts" USING btree ("vehicle_id");
CREATE INDEX "invoices_garage_idx" ON "invoices" USING btree ("garage_id");
CREATE UNIQUE INDEX "invoices_verify_code_uq" ON "invoices" USING btree ("verify_code");
CREATE UNIQUE INDEX "invoices_pay_token_uq" ON "invoices" USING btree ("pay_token");
CREATE UNIQUE INDEX "invoices_garage_number_uq" ON "invoices" USING btree ("garage_id","number");
CREATE INDEX "job_cards_garage_idx" ON "job_cards" USING btree ("garage_id");
CREATE INDEX "job_cards_vehicle_idx" ON "job_cards" USING btree ("vehicle_id");
CREATE UNIQUE INDEX "job_cards_estimate_token_uq" ON "job_cards" USING btree ("estimate_token");
CREATE INDEX "job_items_job_idx" ON "job_items" USING btree ("job_card_id");
CREATE INDEX "checkouts_buyer_idx" ON "checkouts" USING btree ("buyer_id");
CREATE INDEX "payments_ref_idx" ON "payments" USING btree ("ref_id");
CREATE UNIQUE INDEX "reviews_order_product_uq" ON "reviews" USING btree ("order_id","product_id");
CREATE INDEX "reviews_product_idx" ON "reviews" USING btree ("product_id");
CREATE INDEX "reviews_supplier_idx" ON "reviews" USING btree ("supplier_id");

-- Orders placed before v2 went through the legacy flow (escrow held at
-- placement), so they are already paid. Without this, sellers would stop
-- seeing their existing orders.
UPDATE "orders" SET "payment_status" = 'paid';

COMMIT;
